#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/flutter/tasks/code-format-dart.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check or format the Dart files"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="format every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="accepted for the code:format contract"
# USAGE flag "--fix" help="apply fixes"
# USAGE arg "[files]" var=#true help="the files to format; only the .dart files are used; the default is the uncommitted files"
# FILES include="*.dart" exclude="*.g.dart *.freezed.dart *.mocks.dart"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def flag(name):
  """Whether mise gives the flag name as true."""
  return os.environ.get(f"usage_{name}", "false") == "true"


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def main():
  # Shipped with the flutter tool. Without a pubspec.yaml, this is not a Dart
  # project, and the task does not apply and prints nothing.
  root = os.environ["MISE_PROJECT_ROOT"]
  if not os.path.isfile(f"{root}/pubspec.yaml"):
    sys.exit(0)
  os.chdir(root)

  # code:format passes its flags and files to each code:format:* task. The
  # list comes from gate_files (the # FILES header above). An empty list:
  # nothing to do.
  args = [f"--{name}" for name in ("all", "debug", "fix") if flag(name)]
  listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
  try:
    with open(listing, "rb") as data:
      paths = data.read()
    if not paths:
      sys.exit(0)

    helpers.print_header("Formatting the Dart files ...")
    command = ["xargs", "-0", "mise", "x", "--", "dart", "format"]
    if not flag("fix"):
      command += ["--output=none", "--set-exit-if-changed"]
    result = subprocess.run(command, input=paths.replace(b"\n", b"\0"), check=False)
    sys.exit(exit_code(result.returncode))
  finally:
    os.remove(listing)


main()
